import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams, Link } from 'react-router-dom';

function ShowUser() {
  const { id } = useParams();
  const [user, setUser] = useState({});

  useEffect(() => {
    axios.get(`http://localhost:5000/users/${id}`)  // Adjust the URL to your API endpoint
      .then(res => setUser(res.data))
      .catch(err => console.log(err));
  }, [id]);

  return (
    <div className="card card-default">
      <div className="card-header" style={{ marginTop: '10px' }}>
        <h1 className="card-title" style={{ fontSize: '23px' }}>Show User</h1>
        <div className="card-tools">
          <Link to="/users" className="btn btn-sm btn-success">Back</Link>
        </div>
      </div>
      <div className="row" style={{ marginLeft: '20px' }}>
        <div className="col-xs-12 col-sm-12 col-md-12">
          <div className="form-group">
            <strong>Name:</strong>
            {user.name}
          </div>
        </div>
        <div className="col-xs-12 col-sm-12 col-md-12">
          <div className="form-group">
            <strong>Email:</strong>
            {user.email}
          </div>
        </div>
      </div>
    </div>
  );
}

export default ShowUser;
